SELECT (SELECT json_build_object('recordHashes',json_build_object('auth_user',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t))::text,'UTF8')),'hex') AS h FROM brag.auth_user t) rows),'auth_session',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t))::text,'UTF8')),'hex') AS h FROM brag.auth_session t) rows),'auth_account',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t))::text,'UTF8')),'hex') AS h FROM brag.auth_account t) rows),'platform_role',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t))::text,'UTF8')),'hex') AS h FROM brag.platform_role t) rows),'role_audit',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t))::text,'UTF8')),'hex') AS h FROM brag.role_audit t) rows),'event',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t))::text,'UTF8')),'hex') AS h FROM brag.event t) rows),'event_source_alias',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t))::text,'UTF8')),'hex') AS h FROM brag.event_source_alias t) rows),'event_audit',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t))::text,'UTF8')),'hex') AS h FROM brag.event_audit t) rows),'event_mutation',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t))::text,'UTF8')),'hex') AS h FROM brag.event_mutation t) rows),'project_draft',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t) - ARRAY['confirmed_version','confirmed_at','discarded_at','legacy_record'])::text,'UTF8')),'hex') AS h FROM brag.project_draft t) rows),'voice_pitch',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t) - ARRAY['admitted_at','sample_count','legacy_received'])::text,'UTF8')),'hex') AS h FROM brag.voice_pitch t) rows),'draft_mutation',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t))::text,'UTF8')),'hex') AS h FROM brag.draft_mutation t) rows),'agent_handoff',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t) - ARRAY['revoked'])::text,'UTF8')),'hex') AS h FROM brag.agent_handoff t) rows),'agent_request',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t) - ARRAY['state'])::text,'UTF8')),'hex') AS h FROM brag.agent_request t) rows),'processor_config',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t))::text,'UTF8')),'hex') AS h FROM brag.processor_config t) rows),'author_event',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t))::text,'UTF8')),'hex') AS h FROM brag.author_event t) rows),'author_event_mutation',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t))::text,'UTF8')),'hex') AS h FROM brag.author_event_mutation t) rows),'agent_proposal_upload',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t))::text,'UTF8')),'hex') AS h FROM brag.agent_proposal_upload t) rows),'agent_proposal',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to((to_jsonb(t))::text,'UTF8')),'hex') AS h FROM brag.agent_proposal t) rows),'projectConfirmationFacts',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to(to_jsonb(f)::text,'UTF8')),'hex') h FROM (SELECT id,confirmed_version,confirmed_at,discarded_at,legacy_record FROM brag.project_draft) f) rows),'pitchIntakeFacts',(SELECT encode(sha256(convert_to(COALESCE(string_agg(h,'' ORDER BY h),''),'UTF8')),'hex') FROM (SELECT encode(sha256(convert_to(to_jsonb(f)::text,'UTF8')),'hex') h FROM (SELECT id,admitted_at,sample_count,legacy_received FROM brag.voice_pitch) f) rows))))::text AS recovery_hashes;
